function write(route,html){const dir=path.join(root,route);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),html);}
function alias(route,canonical,html){write(route,html.replace(/<link rel="canonical" href="[^"]+">/,`<link rel="canonical" href="${origin}${canonical}">`));}
